nodes.css:
.card {
  position: absolute; left: 120px; top: 776px;
  display: flex; flex-direction: row; align-items: stretch;
  background: rgba(12,13,16,0.92);
  border: 1px solid rgba(244,241,234,0.12); border-radius: 14px;
  box-shadow: 0 10px 28px rgba(0,0,0,0.35);
  overflow: hidden;
}
.bar { width: 7px; background: #d9a441; transform-origin: top center;
  animation: wipe 0.55s cubic-bezier(0.16,1,0.3,1) 0.05s both; }
.body { display: flex; flex-direction: column; justify-content: center;
  gap: 7px; padding: 26px 44px 28px 30px; }
.kicker { font-family: JetBrains Mono, DejaVu Sans Mono, monospace; font-size: 15px; font-weight: 600;
  letter-spacing: 0.28em; color: #d9a441;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.18s both; }
.name { font-family: Archivo, Inter, DejaVu Sans; font-size: 52px; font-weight: 800;
  letter-spacing: -0.02em; color: #f4f1ea; line-height: 1;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.26s both; }
.role { font-family: Inter, DejaVu Sans; font-size: 23px; font-weight: 400;
  color: #9a978e; line-height: 1;
  animation: rise 0.5s cubic-bezier(0.16,1,0.3,1) 0.34s both; }
@keyframes wipe { from { transform: scaleY(0) } to { transform: scaleY(1) } }
@keyframes rise { from { opacity: 0; transform: translateY(10px) } to { opacity: 1; transform: translateY(0) } }
